138	    /**
139	     * Resolve the city for a newly created owner. If an owner already exists in
140	     * that city (matched case-insensitively), reuse that owner's exact spelling;
141	     * otherwise the supplied city is title-cased.
142	     */
143	    private String resolveCity(String city) {
144	        if (city == null) {
145	            return null;
146	        }
147	        return this.clinicService.findAllOwners().stream()
148	            .map(Owner::getCity)
149	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
150	            .findFirst()
151	            .orElseGet(() -> titleCase(city));
152	    }
