154	    /**
155	     * Title-case a city name: the first letter of each whitespace-separated word
156	     * is upper-cased and the remaining letters lower-cased.
157	     */
158	    private String titleCase(String city) {
159	        StringBuilder sb = new StringBuilder(city.length());
160	        boolean startOfWord = true;
161	        for (int i = 0; i < city.length(); i++) {
162	            char c = city.charAt(i);
163	            if (Character.isWhitespace(c)) {
164	                startOfWord = true;
165	                sb.append(c);
166	            } else if (startOfWord) {
167	                sb.append(Character.toUpperCase(c));
168	                startOfWord = false;
169	            } else {
170	                sb.append(Character.toLowerCase(c));
171	            }
172	        }
173	        return sb.toString();
174	    }
