182	    /**
183	     * Resolve the membership tier for a newly created owner: the first
184	     * {@link #FOUNDING_MEMBERSHIP_LIMIT} owners ever created are 'FOUNDING' and
185	     * all later owners are 'STANDARD'.
186	     */
187	    private String resolveMembershipTier() {
188	        long existingOwners = this.clinicService.findAllOwners().size();
189	        return existingOwners < FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD";
