192	    /**
193	     * Build the customer code for a newly created owner, formatted as
194	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
195	     * that already exist in that city, zero-padded to four digits.
196	     */
197	    private String buildCustomerCode(String city) {
198	        long ownersInCity = this.clinicService.findAllOwners().stream()
199	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
200	            .count();
