234	     * is the single most common city among the owners that already exist at the
235	     * moment the new owner is created, otherwise 'remote'. Cities are compared
236	     * case-insensitively. If no owners yet exist, or two or more cities are tied
237	     * for the most common, there is no single most common city and the result is
238	     * 'remote'.
239	     */
240	    private String resolveLocality(String city) {
241	        if (city == null) {
242	            return "remote";
243	        }
244	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
245	            .map(Owner::getCity)
246	            .filter(Objects::nonNull)
247	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(), Collectors.counting()));
248	        if (countsByCity.isEmpty()) {
249	            return "remote";
250	        }
251	        long maxCount = countsByCity.values().stream().max(Long::compareTo).orElse(0L);
252	        long citiesWithMax = countsByCity.values().stream().filter(count -> count == maxCount).count();
253	        boolean cityIsMostCommon = countsByCity.getOrDefault(city.toLowerCase(), 0L) == maxCount;
254	        return citiesWithMax == 1 && cityIsMostCommon ? "local" : "remote";
